import random

def generate(seed):
    rng = random.Random(seed)
    n = rng.randint(3, 10)
    k = rng.randint(1, n - 1)

    # The maximum number of distinct colors needed to color the vertices of G such that no two adjacent vertices share the same color is given by the chromatic number of the graph.
    # For a regular graph with degree k, the chromatic number is at most k + 1.
    answer = k + 1

    # A brute-force check: generate a random graph with n vertices and degree k, and find the chromatic number using a simple greedy algorithm.
    # This is computationally expensive, so we use a simplified approach by generating random graphs and checking the chromatic number.
    check = 0
    for _ in range(1000):  # Perform a large number of trials to approximate the maximum
        G = {i: set() for i in range(n)}
        for i in range(n):
            neighbors = set()
            while len(neighbors) < k:
                j = rng.randint(0, n - 1)
                if i != j and j not in neighbors:
                    neighbors.add(j)
                    G[i].add(j)
                    G[j].add(i)
        colors = [0] * n
        for i in range(n):
            used_colors = {colors[j] for j in G[i]}
            for c in range(1, k + 2):
                if c not in used_colors:
                    colors[i] = c
                    break
        if max(colors) == k + 1:
            check = k + 1
            break

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Let G be a graph with {n} vertices, where each vertex is connected to exactly {k} other vertices. Find the maximum possible number of distinct colors needed to color the vertices of G such that no two adjacent vertices share the same color. State only the integer."
    )

    return problem, str(answer)


